using Microsoft.Xna.Framework;
using System.Text.Json;
namespace StarlightSyndicateDemo;
internal static class ShipBatch26Tests
{
 public static void Run()
 {
  int checks=0;void Check(bool b,string label){if(!b)throw new Exception("BATCH26 FAIL: "+label);checks++;}bool Near(double a,double b)=>Math.Abs(a-b)<.001;
  Check(ShipBatch21.AdvancedDestroyers.Length==15&&FleetCatalog.Playable.Length==400,"15 new / 327 playable");
  var world=new DemoWorld();world.NewGame(0);world.Credits=10000000;
  foreach(var p in ShipBatch21.AdvancedDestroyers){var h=FleetCatalog.ById[p.ShipId];world.Screen=ViewMode.Station;world.Grid="station";world.SystemId=p.HomeSystem;world.Credits=1000000;float cash=world.Credits;
   Check(world.BoardFleetHull(h.Id),"acquire "+h.Name);var ship=world.Player;Check(world.Credits==cash-(float)p.Price,"purchase debits exact price "+h.Name);
   foreach(var a in h.Attributes.Where(a=>ShipAttributeCatalog.ByKey.ContainsKey(a.Key)&&a.Key is not ("cpuLoad" or "powerLoad")))Check(Near(ship.Attributes.GetValueOrDefault(a.Key)??0,a.Value),"preserved source attribute "+h.Name+" "+a.Key);
   Check(world.TotalFitCpu<=ship.Stat("cpuOutput")+.001&&world.TotalFitPower<=ship.Stat("powerOutput")+.001,"legal CPU/grid "+h.Name);
   foreach(string bank in new[]{"high","medium","low"})Check(FittingLayoutModel.Installed(ship).Count(m=>m.Bank==bank)<=ship.Stat(bank=="high"?"hiSlots":bank=="medium"?"medSlots":"lowSlots"),"shared sockets "+h.Name+" "+bank);
   Check(world.CargoUsed<=ship.CargoMax+.001,"finite spare cargo "+h.Name);Check(ship.Drones.Sum(d=>d.Definition.Volume)<=ship.Stat("droneCapacity")&&ship.Drones.Sum(d=>d.Definition.Bandwidth)<=ship.Stat("droneBandwidth"),"legal drone bay "+h.Name);
   Check(double.IsFinite(ship.TotalDps)&&ship.TotalDps>0&&double.IsFinite(ship.EffectiveHitpoints),"finite combat stats "+h.Name);
   var gun=ship.Weapons.FirstOrDefault(s=>s.ModuleId.Length>0&&s.Definition.Kind!=WeaponKind.Bomb);Check(gun!=null,"offensive fit "+h.Name);
   world.Screen=ViewMode.Space;world.Grid="belt";ship.Position=Vector3.Zero;world.Targets=[new(){Id="victim",Kind=TargetKind.Raider,Training=true,Profile=Ship.RaiderProfile(),Position=new(1000,0,0),Signature=10000,Shield=1000000,Armor=1000000,Hull=1000000,Cap=10000}];world.SelectedId=world.LockedId="victim";world.WeaponSafety=false;
   world.Locked!.Profile!.SetStat("shieldCapacity",1000000);world.Locked.Profile.SetStat("armorHP",1000000);world.Locked.Profile.SetStat("hp",1000000);world.Locked.Profile.SetStat("signatureRadius",10000);
   world.ToggleWeapon(Array.IndexOf(ship.Weapons,gun!));Check(gun!.Active,"real gun activation "+h.Name);for(int i=0;i<750;i++)world.Update(.05f);Check(world.Locked!.Shield+world.Locked.Armor+world.Locked.Hull<3000000,"live weapon damage "+h.Name);foreach(var s in ship.Weapons)s.Stop();world.MissilesInFlight.Clear();
   ship.Cap=ship.MaxCap;
   if(p.Role=="Interdictor"){
    Check(ship.Ewar[0].Definition?.Kind==EwarKind.Sphere,"probe rack installed "+h.Name);world.SystemId="rim";int probes=ship.Ewar[0].Loaded;world.ToggleEwar(0);world.Update(.05f);Check(world.EwarZones.Count==1&&ship.Ewar[0].Loaded==probes-1,"live bubble consumes probe "+h.Name);Check(world.WarpBlocked("player")&&world.WarpBlocked("victim"),"bubble blocks self and hostile "+h.Name);var zone=world.EwarZones[0];ship.Position=new(100000,0,0);Check(!world.WarpBlocked("player")&&zone.Center==Vector3.Zero,"bubble remains at launch point "+h.Name);world.Update(zone.Remaining+.1f);Check(world.EwarZones.Count==0,"bubble expires "+h.Name);world.SystemId="aster";ship.Ewar[0].Cooldown=0;ship.Ewar[0].ReloadLeft=0;world.ToggleEwar(0);Check(!ship.Ewar[0].Active,"high security interdiction rejected "+h.Name);world.SystemId="rook";
   }
   if(ship.HullCapability("micro jump field generators")){
    Check(world.BurstLimit==1&&ship.Support.Any(s=>s.Definition?.Kind=="Burst"),"one real command burst "+h.Name);int burst=Array.FindIndex(ship.Support,s=>s.Definition?.Kind=="Burst");int charges=ship.Support[burst].Loaded;Check(world.ToggleSupport(burst),"burst activates "+h.Name);Check(ship.Support[burst].Loaded==charges-1&&ship.SupportEffects.Any(e=>e.Burst),"charge spent and bonuses applied "+h.Name);var second=SupportCatalog.All.First(d=>d.Kind=="Burst");Check(world.SupportFitError(second,1).Length>0,"second burst rejected "+h.Name);
    world.SystemId="rook";ship.Cap=ship.MaxCap;ship.Position=Vector3.Zero;ship.Facing=Vector3.UnitZ;world.Targets=[new(){Id="hostile",Kind=TargetKind.Raider,Training=false,Profile=Ship.RaiderProfile(),Position=new(100,0,0)},new(){Id="scrammed",Kind=TargetKind.Raider,Training=false,Profile=Ship.RaiderProfile(),Position=new(200,0,0)},new(){Id="outside",Kind=TargetKind.Raider,Training=false,Profile=Ship.RaiderProfile(),Position=new(20000,0,0)}];world.EwarEffects=[new(){SourceId="hostile",TargetId="scrammed",Kind=EwarKind.Scram,Strength=2,Remaining=100}];int field=Array.FindIndex(ship.Mobility,s=>s.Definition?.Kind=="Field");Check(field>=0&&world.ToggleMobility(field),"field spool activates "+h.Name);var state=ship.Mobility[field];Check(Near(state.CycleLeft,state.Definition!.Cycle*.95),"proficiency I spool reduction "+h.Name);world.UpdateMobility(state.CycleLeft+.01f);Check(ship.Position.Z==state.Definition.JumpRange&&world.Targets[0].Position.Z==state.Definition.JumpRange&&world.LastMobilityPassengers==1,"real hostile passenger jumps "+h.Name);Check(world.Targets[1].Position.Z==0&&world.Targets[2].Position.Z==0,"scrammed and outside passengers excluded "+h.Name);Check(!world.ToggleMobility(field),"reactivation cooldown enforced "+h.Name);
   }
   if(p.Role=="TacticalDestroyer"){
    Check(ship.HullTacticalMode=="Primary","defense default "+h.Name);double speed=ship.Stat("maxVelocity"),agility=ship.Stat("agility"),range=ship.Stat("maxTargetRange");Check(world.SetHullTacticalMode("Secondary")&&ship.Stat("agility")<agility,"propulsion mode live inertia "+h.Name);Check(Near(ship.HullTacticalCooldown,h.SourceHull=="Skua"?2:10)&&!world.SetHullTacticalMode("Tertiary"),"source mode switch timer "+h.Name);world.Update(ship.HullTacticalCooldown+.01f);Check(world.SetHullTacticalMode("Tertiary")&&Near(ship.Stat("maxTargetRange"),range*2),"sharpshooter sensor range "+h.Name);Check(ship.HullWeapon(gun!.Definition,"damage")>1.7,"sharpshooter actual damage factor "+h.Name);Check(Near(ship.Stat("sensorDampenerResistance"),.334)&&Near(ship.Stat("weaponDisruptionResistance"),.334),"hostile EW resistance "+h.Name);
   }
   if(h.SourceHull=="Outrider"){
    int miner=Array.FindIndex(ship.Utilities,u=>u.Definition?.Kind=="Miner");Check(miner>=0,"Tonnage factory harvester fitted");ship.Position=Vector3.Zero;ship.Cap=ship.MaxCap;world.Targets=[new(){Id="ore",Kind=TargetKind.Asteroid,Resource="ore",Position=new(1000,0,0),Ore=100000}];world.SelectedId=world.LockedId="ore";Check(world.ToggleUtility(miner),"Tonnage live mining activation");var u=ship.Utilities[miner];float expected=MathF.Floor(u.Definition!.Amount*1.15f/DemoWorld.ItemVolume("ore"));world.UpdateUtility(u.CycleDuration+.01f);Check(Near(world.ItemCount("ore",false),expected)&&world.Targets[0].Ore<100000,"Tonnage bonused finite harvest");world.StopUtility(u);float general=world.CargoUsed;ship.Ore=20000;Check(world.CargoAllocation().Holds.Single(v=>v.Key=="generalMiningHoldCapacity").Used==20000&&world.CargoUsed<=general+.001,"Tonnage 20000 m3 mining hold active");Check(world.CargoRoom("salvage")<=ship.CargoMax&&world.CargoRoom("ore")<=ship.CargoMax,"Full mining hold retains general hold boundaries");
   }
   world.Screen=ViewMode.Station;world.Targets.Clear();world.MissilesInFlight.Clear();world.EwarEffects.Clear();world.EwarZones.Clear();Console.WriteLine("BATCH26 PASS: "+h.Faction+" / "+h.Name+" / "+p.Role);
  }
  Ship Hull(string name,int level=5){var s=new Ship();s.ApplyFleetHull(FleetCatalog.Source(name));foreach(int skill in ShipBatch21.ById[s.CombatHull].Traits.Where(t=>t.Skill!=0).Select(t=>t.Skill).Distinct())s.HullProficiency[skill]=level;return s;}
  var hybrid=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Railguns");var missile=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Missile Launcher Light");var rocket=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Missile Launcher Rocket");
  Check(Near(Hull("Eris").HullFactor("plate","mass"),0)&&Near(Hull("Eris").HullWeapon(hybrid,"cycle"),.625),"Eris V plate mass / hybrid cycle");
  Check(Near(Hull("Flycatcher").HullWeapon(missile,"damage","Kinetic"),1.5)&&Near(Hull("Flycatcher").HullWeapon(missile,"damage","EM"),1),"Flycatcher typed missile damage");
  foreach(var p in ShipBatch21.AdvancedDestroyers){var ship=Hull(FleetCatalog.ById[p.ShipId].SourceHull);foreach(var effect in p.Effects.Where(e=>e.Skill!=0)){Check(ship.HullProficiency[effect.Skill]==5,"V proficiency "+p.ShipId+effect.Key);}}
  var hecate=Hull("Hecate");Check(Near(hecate.HullFactor("local","cycle","Armor"),.667)&&Near(hecate.Stat("hullThermalDamageResonance")/FleetCatalog.Source("Hecate").Value("hullThermalDamageResonance"),.667),"Hecate defense repair and hull resonance");hecate.HullTacticalMode="Secondary";Check(Near(hecate.HullFactor("prop","speed","MWD"),1.666)&&Near(hecate.HullFactor("prop","cap","MWD"),.334)&&Near(hecate.HullFactor("prop","speed","AB"),1),"Hecate MWD-only propulsion");
  var skua=Hull("Skua");skua.HullTacticalMode="Tertiary";Check(Near(skua.HullWeapon(rocket,"missileVelocity"),3.5)&&Near(skua.HullWeapon(missile,"missileVelocity"),1.666),"Skua distinct rocket and light missile speeds");
  foreach(string name in new[]{"Magus","Stork","Pontifex","Bifrost","Outrider","Draugur","Skua"}){var ship=Hull(name);Check(Near(ship.HullFactor("prop","cycle","Field"),.75),name+" V field spool");Check(Near(ship.HullFactor("support","power","Burst"),.05),name+" burst grid");foreach(var e in ShipBatch21.ById[ship.CombatHull].Effects.Where(e=>e.System=="burst"))Check(Near(ship.HullFactor(e.System,e.Key,e.Filter),1.1),name+" burst V "+e.Filter);}
  var outrider=Hull("Outrider");Check(Near(outrider.HullFactor("utility","range","Tractor"),1.75)&&Near(outrider.HullFactor("utility","speed","Tractor"),1.3)&&Near(outrider.HullFactor("harvest","yield"),1.75),"Outrider actual mining / tractor factors");
  var reject=new DemoWorld();reject.NewGame(0);var paid=ShipBatch21.AdvancedDestroyers.First();reject.SystemId=paid.HomeSystem;reject.Credits=0;Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0,"insufficient purchase atomic");reject.Credits=100000;reject.SystemId="rook";Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0,"wrong station atomic");
  string save=Path.Combine(Path.GetTempPath(),"batch26-"+Guid.NewGuid());var previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");try{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",save);world.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.GrantedFleetHulls.Intersect(ShipBatch21.AdvancedDestroyers.Select(p=>p.ShipId)).Count()==15,"all fifteen ownership restore");foreach(var p in ShipBatch21.AdvancedDestroyers){var old=world.Player.CombatHull==p.ShipId?world.Player:world.FleetBerths.Single(b=>b.Ship.CombatHull==p.ShipId).Ship;var copy=loaded.Player.CombatHull==p.ShipId?loaded.Player:loaded.FleetBerths.Single(b=>b.Ship.CombatHull==p.ShipId).Ship;Check(old.HullTacticalMode==copy.HullTacticalMode&&Near(old.HullTacticalCooldown,copy.HullTacticalCooldown),"saved mode and timer "+p.ShipId);Check(old.Attributes.SequenceEqual(copy.Attributes),"saved attributes "+p.ShipId);Check(JsonSerializer.Serialize(FittingLayoutModel.Installed(old))==JsonSerializer.Serialize(FittingLayoutModel.Installed(copy)),"saved complete fits "+p.ShipId);}}
  finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(save))Directory.Delete(save,true);}
  Console.WriteLine($"{checks} advanced destroyer checks passed / 15 hulls.");
 }
}
